CREATE TRIGGER RefCusPreference_Version_Create
	ON RefCusPreference
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZZS_PK, 'ZZS'
	FROM inserted
GO
CREATE TRIGGER RefCusPreference_Version_Update
	ON RefCusPreference
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZZS_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
